public boolean catalogRecognizesNonNull(String typeName) {
	if (typeName == null) return false;
	if (languageNonNullCatalog.contains(typeName)) return true;
	int dot = typeName.lastIndexOf('.');
	String simple = dot < 0 ? typeName : typeName.substring(dot + 1);
	return languageNonNullSimpleNames.contains(simple);
}

public boolean catalogRecognizesCopyable(String typeName) {
	if (typeName == null) return false;
	if (copyableAnnotationCatalog.contains(typeName)) return true;
	int dot = typeName.lastIndexOf('.');
	String simple = dot < 0 ? typeName : typeName.substring(dot + 1);
	return copyableAnnotationSimpleNames.contains(simple);
}

