public void emitFlagUsage(JavacNode node, ConfigurationKey<FlagUsageType> key, String featureName) {
	rememberAnnotationNode(node);
	FlagUsageType fut = node.getAst().readConfiguration(key);
	if (fut != null) {
		String msg = "Use of " + featureName + " is flagged according to lombok configuration.";
